pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherLotto c;

    function setUp() public {
        c = new EtherLotto();
    }

    function _run(uint256 playAmount) internal {
        playAmount = bound(playAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(true);
        try c.play{value: playAmount}() {} catch { return; }
        assertTrue(c.pot() == 0 || (c.pot() % 10 == 0 && c.pot() > 1));
    }

    function testFuzz_run(uint256 playAmount) public {
        _run(playAmount);
    }

    receive() external payable {}
}
